private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Step 1: Check if the current index is within the bounds of the ByteBuffer
    if (i >= bb.limit()) {
        // If the index is out of bounds, return -1
        return -1;
    }

    byte b = bb.get(i);

    // Step 2: Decode the current octet using the UTF-8 decoding scheme
    int codePoint;
    if (b < 0x80) {
        // If the current octet is a single byte, return its value as the code point
        codePoint = b;
    } else if (b < 0xC2 || b > 0xF4) {
        // If the current octet is an invalid start byte, return -1
        return -1;
    } else {
        // If the current octet is a lead byte, extract the continuation bits and the code point from the next octets
        int continuationBits = b - 0xC0;
        int lowerOctet = bb.get(i + 1);
        int upperOctet = bb.get(i + 2);
        codePoint = (lowerOctet << 8) + upperOctet;
        if (codePoint <= 0x3000) {
            // If the code point is an overlong encoding, return -1
            return -1;
        }
    }

    // Step 3: Append the decoded character to the StringBuilder
    sb.appendCodePoint(codePoint);

    // Step 4: Return the index of the next unchecked character in the string
    return i + 1;
}

