private void enlarge(final int size) {
    // Step 1: Check if the vector has enough capacity to hold the additional bytes
    if (size > 0) {
        // Step 2: Calculate the new capacity needed
        int newCapacity = buffer.length + size;
        if (newCapacity < 0) {
            throw new IllegalArgumentException("New capacity exceeds the maximum array size");
        }
        // Step 3: Create a new array with the new capacity
        byte[] newBuffer = new byte[newCapacity];
        // Step 4: Copy the contents of the old buffer to the new buffer
        System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
        // Step 5: Set the new buffer as the current buffer
        buffer = newBuffer;
    }
}

