public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
  // Step 1: Initialize the graph
  Graph<V,E> resultGraph = new Graph<>();

  // Step 2: Add vertices to the graph
  for (Map.Entry<String,V> entry : resultMap.entrySet()) {
    resultGraph.addVertex(entry.getValue());
  }

  // Step 3: Add edges to the graph
  for (Map.Entry<String,V> entry : resultMap.entrySet()) {
    String vertexName = entry.getKey();
    V vertexValue = entry.getValue();

    // Add edges to all vertices in the result map that have the same name as the vertex being processed
    for (Map.Entry<String,V> otherEntry : resultMap.entrySet()) {
      String otherVertexName = otherEntry.getKey();
      V otherVertexValue = otherEntry.getValue();

      if (vertexName.equals(otherVertexName)) {
        resultGraph.addEdge(vertexValue, otherVertexValue);
      }
    }
  }

  // Step 4: Return the resulting graph
  target.putGraph(resultGraph);
}

