int addType(final String value){
  // Check if the type table already contains a similar type
  if (typeTable.containsKey(value)) {
    // If so, return the index of the existing type Symbol
    return typeTable.get(value).getIndex();
  }

  // Otherwise, create a new type Symbol with the given value
  TypeSymbol typeSymbol = new TypeSymbol(value);

  // Add the new type symbol to the type table
  typeTable.put(value, typeSymbol);

  // Return the index of the new type symbol
  return typeSymbol.getIndex();
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            Type typeArgument = typeArguments[i];
            if (typeArgument instanceof Class) {
                resolvedArguments[i] = (Class<?>) typeArgument;
            } else if (typeArgument instanceof TypeVariable) {
                TypeVariable typeVariable = (TypeVariable) typeArgument;
                resolvedArguments[i] = resolveTypeVariable(typeVariable, targetType);
            } else if (typeArgument instanceof WildcardType) {
                WildcardType wildcardType = (WildcardType) typeArgument;
                resolvedArguments[i] = resolveWildcardType(wildcardType, targetType);
            } else {
                throw new IllegalArgumentException("Unsupported type: " + typeArgument);
            }
        }
        return resolvedArguments;
    }
    return null;
}

@Override
public void accept(final METRICS data) {
    // Handle null data
    if (data == null) {
        throw new IllegalArgumentException("Data cannot be null");
    }

    // Lock the cache to prevent concurrent modification
    synchronized (this) {
        // Check if the cache contains the key
        if (this.containsKey(data.getKey())) {
            // Merge the data with the existing value
            METRICS existingValue = this.get(data.getKey());
            existingValue.merge(data);
        } else {
            // Add the data to the cache
            this.put(data.getKey(), data);
        }
    }
}

