static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("Day step must be greater than 0.");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("Time bucket must be greater than 0.");
    }

    long reFormattedTimeBucket = timeBucket;

    // Calculate the start and end dates of the time bucket
    LocalDate startDate = LocalDate.ofEpochDay(timeBucket);
    LocalDate endDate = startDate.plusDays(dayStep - 1);

    // If the end date is before the start date, then the time bucket is invalid
    if (endDate.isBefore(startDate)) {
        throw new IllegalArgumentException("Invalid time bucket.");
    }

    // Calculate the new start date
    LocalDate newStartDate = startDate.withDayOfMonth(1);

    // If the new start date is after the end date, then the time bucket is invalid
    if (newStartDate.isAfter(endDate)) {
        throw new IllegalArgumentException("Invalid time bucket.");
    }

    // Calculate the new end date
    LocalDate newEndDate = newStartDate.plusDays(dayStep - 1);

    // If the new end date is before the new start date, then the time bucket is invalid
    if (newEndDate.isBefore(newStartDate)) {
        throw new IllegalArgumentException("Invalid time bucket.");
    }

    // Calculate the new time bucket
    reFormattedTimeBucket = newEndDate.toEpochDay();

    return reFormattedTimeBucket;
}

