public static int getUTF8Size(char c) {
    int size = 1;
    if (c < 0x80) {
        // Single byte character
        size = 1;
    } else if (c < 0x800) {
        // Two-byte character
        size = 2;
    } else if (c < 0x10000) {
        // Three-byte character
        size = 3;
    } else if (c < 0x110000) {
        // Four-byte character
        size = 4;
    }
    return size;
}

