public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
  /*
   * To decode the path component of a URI, we need to split the component into path segments using the '/' delimiter.
   * If the path component is an absolute path component, the leading '/' is ignored and is not considered a delimiator of a path segment.
   * We also need to handle the case where the path component is empty or consists only of '/' characters.
   * Finally, if decode is true, we need to decode the path segments using the URLDecoder class.
   */

  // Check if the path component is null or empty
  String path = u.getPath();
  if (path == null || path.isEmpty()) {
    return Collections.emptyList();
  }

  // Split the path component into path segments using the '/' delimiter
  String[] segments = path.split("/");
  if (segments.length == 0) {
    return Collections.emptyList();
  }

  // Handle the case where the path component is an absolute path component
  int startIndex = (segments[0] == "/" ? 1 : 0);

  // Create a list to store the path segments
  List<PathSegmentImpl> segmentsList = new ArrayList<>();

  // Iterate over the path segments and decode them if necessary
  for (int i = startIndex; i < segments.length; i++) {
    String segment = segments[i];
    if (decode && segment.length() > 0) {
      try {
        segment = URLDecoder.decode(segment, "UTF-8");
      } catch (UnsupportedEncodingException e) {
        throw new IllegalArgumentException("Unsupported encoding", e);
      }
    }
    segmentsList.add(new PathSegmentImpl(segment));
  }

  return segmentsList;
}

