  if (desiredCapacity < 0) {
    throw new IllegalArgumentException("Desired capacity must be non-negative");
  }

  int capacity = 0;
  for (int i = 2; i <= desiredCapacity; i++) {
    boolean isPrime = true;
    for (int j = 2; j < i; j++) {
      if (i % j == 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) {
      capacity = i;
      break;
    }
  }

  if (capacity <= desiredCapacity * 0.89) {
