public final byte[] toByteArray() {
    /* Step 1: Check if the buffer is empty */
    if (buffer.size() == 0) {
        return new byte[0];
    }

    /* Step 2: Calculate the total length of the buffer */
    int totalLength = 0;
    for (ByteBuffer buffer : buffers) {
        totalLength += buffer.capacity();
    }

    /* Step 3: Allocate a new byte array of the total length */
    byte[] result = new byte[totalLength];

    /* Step 4: Copy each buffer's contents into the byte array */
    int offset = 0;
    for (ByteBuffer buffer : buffers) {
        buffer.flip();
        buffer.get(result, offset, buffer.limit());
        offset += buffer.limit();
        buffer.clear();
    }

    return result;
}

