public final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
        // Check for invalid constant pool entry index
        if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= this.constantPool.size()) {
            throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
        }

        // Check for null char buffer
        if (charBuffer == null) {
            throw new NullPointerException("Char buffer cannot be null");
        }

        ConstantPoolInfo constantPoolInfo = this.constantPool.get(constantPoolEntryIndex);
        if (constantPoolInfo instanceof ConstantUtf8Info) {
            ConstantUtf8Info utf8Info = (ConstantUtf8Info) constantPoolInfo;
            String string = new String(utf8Info.getBytes(), StandardCharsets.UTF_8);
            if (string.length() > charBuffer.length) {
                throw new BufferOverflowException("Char buffer is not large enough to hold the string");
            }
            for (int i = 0; i < string.length(); i++) {
                charBuffer[i] = string.charAt(i);
            }
            return string;
        } else {
            throw new IllegalArgumentException("Not a UTF-8 constant pool entry: " + constantPoolInfo);
        }
    }

