private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {

  OuterFaceCirculator circulator = new OuterFaceCirculator();
  Node current = start;
  Node previous = ciruclar.last();
  int count = 0;

  while (current != stop) {
    if (predicate.test(current)) {
      circulator.setCurrent(current);
      circulator.setPrevious(previous);
      circulator.setCount(count);
      return circulator;
    }
    previous = current;
    current = current.getNext();
    count++;
  }

  throw new NoSuchElementException("No node found on the outer face that satisfies the predicate");
}

