public final MatchResult match(CharSequence uri){
	// Step 1: Validate input
	if (uri == null || uri.length() == 0) {
		throw new IllegalArgumentException("URI must not be null or empty");
	}

	// Step 2: Parse URI into its components
	String[] uriComponents = uri.toString().split("/");

	// Step 3: Match URI components against the pattern
	List<String> matchedComponents = new ArrayList<>();
	for (int i = 0; i < uriComponents.length; i++) {
		String component = uriComponents[i];
		String patternComponent = getPatternComponent(i);

		if (component.equals(patternComponent)) {
			matchedComponents.add(component);
		} else if (patternComponent.startsWith("{") && patternComponent.endsWith("}")) {
			int patternVariableId = getPatternVariableId(patternComponent);
			String variableValue = getVariableValue(uri, i, patternVariableId);
			if (variableValue == null) {
				return null;
			}
			matchedComponents.add(variableValue);
		} else {
			return null;
		}
	}

	// Step 4: Return match result
	return new MatchResult(matchedComponents.toArray(new String[0]), uriComponents.length);
}

