    }

    // Step 2: Check if the bucket is same as the dataset
    if (this.getId().equals(dataset.getId())) {
        return true;
    }

    // Step 3: Check if the bucket is same as the dataset's parent bucket
    DataBucket parentBucket = dataset.getParentBucket();
    if (parentBucket != null && this.getId().equals(parentBucket.getId())) {
        return true;
    }

    // Step 4: Check if the dataset is a child dataset of the bucket
    if (dataset.getParentBucket() != null && this.getId().equals(dataset.getParentBucket().getId())) {
        return true;
    }

    return false;
}

