private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) throws IllegalArgumentException {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Bounds list must not be null or empty.");
    }
    List<Integer> suffixSums = new ArrayList<>(bounds.size());
    long totalSum = 0;
    for (int i = 0; i < bounds.size(); i++) {
        Integer curr = bounds.get(i);
        if (curr == null) {
            throw new IllegalArgumentException("Bounds list must not contain null elements.");
        }
        if (curr < 0) {
            throw new IllegalArgumentException("Bounds list must only contain non-negative integers.");
        }
        suffixSums.add(curr);
        totalSum += curr;
    }
    return Pair.of(suffixSums, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
  if (arr == null || arr.length == 0 || from < 0 || to < 0 || from >= arr.length || to >= arr.length) {
    throw new IllegalArgumentException("Invalid input");
  }

  int mid = (from + to) / 2;
  for (int i = from; i <= mid; i++) {
    int mirrorIndex = to - (i - from);
    V temp = arr[i];
    arr[i] = arr[mirrorIndex];
    arr[mirrorIndex] = temp;
  }
}

