public ByteVector putInt(final int intValue){
    final int byteCount = 4;
    final int pos = this.position;

    if (byteCount < 0) {
        throw new IllegalArgumentException("byteCount must be non-negative");
    }

    final int newPosition = pos + byteCount;
    ensureCapacity(newPosition);

    final byte[] b = new byte[byteCount];
    for (int i = 0; i < byteCount; i++) {
        b[i] = (byte) (intValue >>> (8 * (byteCount - i - 1)));
    }

    System.arraycopy(b, 0, this.data, pos, byteCount);
    this.position = newPosition;

    return this;
}

