public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid name start index");
    }

    int i = nameStart;
    while (i < buf.length() && Character.isLetter(buf.charAt(i))) {
        i++;
    }
    if (i > nameStart) {
        buf.setCharAt(nameStart, Character.toUpperCase(buf.charAt(nameStart)));
        for (int j = nameStart + 1; j < i; j++) {
            buf.setCharAt(j, '.');
        }
    }
}

