private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    boolean isClique = true;
    Set<V> neighbors = new HashSet<>();
    for (V vertex : vertices) {
        neighbors.addAll(graph.getNeighbors(vertex));
    }
    if (neighbors.size() != vertices.size()) {
        isClique = false;
    }
    return isClique;
}

private List<Integer> computeLowerBounds(List<K> keys) {
  /*
   * Step 1: Sort the keys in ascending order.
   */
  Collections.sort(keys);

  /*
   * Step 2: Initialize the lower bound for each key as the minimum value of the key.
   */
  List<Integer> lowerBounds = new ArrayList<>(keys.size());
  for (K key : keys) {
    lowerBounds.add(key.getLowerBound());
  }

  /*
   * Step 3: Update the lower bound for each key based on the lower bounds of the previous and next keys.
   */
  for (int i = 1; i < keys.size() - 1; i++) {
    K currentKey = keys.get(i);
    K previousKey = keys.get(i - 1);
    K nextKey = keys.get(i + 1);

    int currentLowerBound = lowerBounds.get(i);
    int previousLowerBound = lowerBounds.get(i - 1);
    int nextLowerBound = lowerBounds.get(i + 1);

    int minLowerBound = Math.min(currentLowerBound, Math.min(previousLowerBound, nextLowerBound));

    lowerBounds.set(i, minLowerBound);
  }

  return lowerBounds;
}

private void pop(final String descriptor) {
    // Step 1: Parse the given descriptor to determine the number of types to pop
    String[] tokens = descriptor.split("\\s+");
    int numTypes = 0;
    for (String token : tokens) {
        if (token.equals("()")) {
            // End of method arguments
            break;
        } else if (token.equals(")")) {
            // End of method return type
            break;
        } else if (token.equals(",") || token.equals(".")) {
            // Skip separators
            continue;
        } else if (token.equals("V")) {
            // Void return type
            break;
        }
        numTypes++;
    }

    // Step 2: Pop the specified number of types from the output frame stack
    for (int i = numTypes - 1; i >= 0; i--) {
        Class<?> type = stack.pop();
        if (type == null) {
            throw new RuntimeException("Failed to pop type from stack: empty stack");
        }
    }
}

