public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshotList = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        for (String line; (line = reader.readLine()) != null; ) {
            // Parse the line
            String[] parts = line.split("\\s+");
            if (parts.length < 2) {
                throw new IOException("Invalid line format: " + line);
            }
            long time = Long.parseLong(parts[0]);
            long threadId = Long.parseLong(parts[1]);
            String threadName = parts[2];
            String status = parts.length > 3 ? parts[3] : null;
            List<TraceEvent> traceEvents = new ArrayList<>();
            for (int i = 0; i < parts.length; i += 2) {
                long traceId = Long.parseLong(parts[i]);
                long startTime = Long.parseLong(parts[i + 1]);
                long endTime = Long.parseLong(parts[i + 2]);
                traceEvents.add(new TraceEvent(traceId, startTime, endTime));
            }
            ThreadSnapshot snapshot = new ThreadSnapshot(time, threadId, threadName, status, traceEvents);
            snapshotList.add(snapshot);
        }
    } catch (IOException e) {
        throw new IOException("Error parsing thread snapshots from file", e);
    }
    return snapshotList;
}
